from typing import Dict, List, Optional, Set


class Solution:
    def maximalSquare(self, matrix: List[List[str]]) -> int:
        rows = len(matrix)
        cols = len(matrix[0])

        OFF = "0"
        MARKED = ""

        maxSqr = 0

        for r in range(rows):
            for c in range(cols):
                root = matrix[r][c]
                if root == MARKED or root == OFF:
                    continue  # ignore visited places, and 0 cannot be start of the square

                side = 1  # max side length reached
                verOkay = True
                horOkay = True

                if r == 12 and c == 8:
                    matrix[r][c] = "X"
                    matrixPrint([matrix[i][0:20] for i in range(0, 20)])

                while verOkay and horOkay and r + side < rows and c + side < cols:

                    for i in range(side + 1):
                        # ver check
                        if matrix[r + i][c + side] == OFF:
                            verOkay = False
                            break

                        # hor check
                        if matrix[r + side][c + i] == OFF:
                            horOkay = False
                            break

                    if verOkay and horOkay:
                        for i in range(side):
                            # mark checked areas of last cycle, so that if the current is last layer, dont mark
                            # because they can be part of new square
                            matrix[r + i][c + side - 1] = MARKED
                            matrix[r + side - 1][c + i] = MARKED

                        side += 1
                if side * side > maxSqr:
                    matrix[r][c] = "M"
                    print(f"({r},{c}): {side * side}")
                maxSqr = max(maxSqr, side * side)

        return maxSqr


def matrixPrint(mat: List[List[int]]):
    for row in mat:
        print(" ".join([(str(c) if str(c) != "" else "_") for c in row]))


